import { redactFaces, registerDerivation } from '@projexlight/hdk-image-editor';
const result = await redactFaces({ source_blob_id });
const variant = await registerDerivation({
  source_evidence_id, derivation_kind: 'face-redacted',
  derived_blob: result.derived_blob,
  detector_metadata: result.detector_metadata,
});

import { redactText, registerDerivation } from '@projexlight/hdk-image-editor';
const result = await redactText({ source_blob_id, target_pattern: 'license-plate' });
await registerDerivation({ source_evidence_id, derivation_kind: 'plate-redacted', ...result });

import { applyOp } from '@projexlight/hdk-image-editor';
const annotated = await applyOp({
  source_blob_id,
  op_kind: 'annotate',
  params: { shapes: [{ kind: 'arrow', from: [120, 80], to: [200, 240] }] },
});

const r = await fetch('/api/hdk/image-editor/capabilities', { headers: { Authorization: 'Bearer ' + jwt } });
const { ops } = (await r.json()).data;
if (ops.includes('redact-text')) showPlateStripButton();
